```php
<?php

final class FastScanner
{
    private string $data;
    private int $index = 0;
    private int $length;

    public function __construct()
    {
        $this->data = file_get_contents("php://stdin");
        $this->length = strlen($this->data);
    }

    public function nextInt(): int
    {
        while ($this->index < $this->length && ord($this->data[$this->index]) <= 32) {
            ++$this->index;
        }

        $number = 0;
        while ($this->index < $this->length) {
            $code = ord($this->data[$this->index]);
            if ($code < 48 || $code > 57) {
                break;
            }
            $number = $number * 10 + ($code - 48);
            ++$this->index;
        }

        return $number;
    }
}

$scanner = new FastScanner();
$t = $scanner->nextInt();
$output = [];

for ($case = 0; $case < $t; ++$case) {
    $n = $scanner->nextInt();

    $prefix = [0];
    $sum = 0;

    for ($i = 1; $i <= $n; ++$i) {
        $sum += $scanner->nextInt();
        $prefix[$i] = $sum;
    }

    $answer = 0;

    for ($k = 1; $k < $n; ++$k) {
        if ($n % $k !== 0) {
            continue;
        }

        $minimum = PHP_INT_MAX;
        $maximum = PHP_INT_MIN;

        for ($end = $k; $end <= $n; $end += $k) {
            $truckWeight = $prefix[$end] - $prefix[$end - $k];

            if ($truckWeight < $minimum) {
                $minimum = $truckWeight;
            }
            if ($truckWeight > $maximum) {
                $maximum = $truckWeight;
            }
        }

        $difference = $maximum - $minimum;
        if ($difference > $answer) {
            $answer = $difference;
        }
    }

    $output[] = (string)$answer;
}

echo implode("\n", $output);
?>
