$lines = file('php://stdin', FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES);

$cost = [];
$time = [];

if (isset($lines[0])) {
    preg_match_all('/-?\d+/', $lines[0], $matches);
    $cost = array_map('intval', $matches[0]);
}

if (isset($lines[1])) {
    preg_match_all('/-?\d+/', $lines[1], $matches);
    $time = array_map('intval', $matches[0]);
}

$n = count($cost);
$infinity = PHP_INT_MAX;
$dp = array_fill(0, $n + 1, $infinity);
$dp[0] = 0;

for ($i = 0; $i < $n; $i++) {
    $capacity = $time[$i] + 1;

    for ($painted = $n - 1; $painted >= 0; $painted--) {
        if ($dp[$painted] === $infinity) {
            continue;
        }

        $next = min($n, $painted + $capacity);
        $newCost = $dp[$painted] + $cost[$i];

        if ($newCost < $dp[$next]) {
            $dp[$next] = $newCost;
        }
    }
}

echo $dp[$n], PHP_EOL;
