$input = file_get_contents("php://stdin");
preg_match_all('/-?\d+/', $input, $matches);
$nums = array_map('intval', $matches[0]);

$n = count($nums);
$seen = array_fill(0, $n + 2, 0);
$answer = 0;

for ($left = 0; $left < $n; $left++) {
    $generation = $left + 1;
    $imbalance = 0;
    $seen[$nums[$left]] = $generation;

    for ($right = $left + 1; $right < $n; $right++) {
        $value = $nums[$right];

        if ($seen[$value] !== $generation) {
            $hasLeftNeighbor = ($seen[$value - 1] === $generation);
            $hasRightNeighbor = ($seen[$value + 1] === $generation);

            $imbalance += 1
                - ($hasLeftNeighbor ? 1 : 0)
                - ($hasRightNeighbor ? 1 : 0);

            $seen[$value] = $generation;
        }

        $answer += $imbalance;
    }
}

echo $answer;
