$input = trim(stream_get_contents(STDIN));
$words = [];

$decoded = json_decode($input, true);

if (is_array($decoded)) {
    if (isset($decoded['words']) && is_array($decoded['words'])) {
        $decoded = $decoded['words'];
    }

    foreach ($decoded as $value) {
        if (is_string($value)) {
            $words[] = $value;
        }
    }
}

if (empty($words)) {
    preg_match_all('/[a-z]+/', $input, $matches);
    $words = $matches[0];

    if (preg_match('/^\s*words\s*=/', $input) && isset($words[0]) && $words[0] === 'words') {
        array_shift($words);
    }
}

$n = count($words);

if ($n === 0) {
    echo "0\n";
    exit;
}

$states = 26 * 26;
$inf = PHP_INT_MAX;
$dp = array_fill(0, $states, $inf);

$firstWord = $words[0];
$firstChar = ord($firstWord[0]) - 97;
$lastChar = ord($firstWord[strlen($firstWord) - 1]) - 97;
$dp[$firstChar * 26 + $lastChar] = strlen($firstWord);

for ($i = 1; $i < $n; $i++) {
    $word = $words[$i];
    $length = strlen($word);
    $wordFirst = ord($word[0]) - 97;
    $wordLast = ord($word[$length - 1]) - 97;

    $next = array_fill(0, $states, $inf);

    for ($state = 0; $state < $states; $state++) {
        if ($dp[$state] === $inf) {
            continue;
        }

        $currentFirst = intdiv($state, 26);
        $currentLast = $state % 26;

        // join(current string, word)
        $newState = $currentFirst * 26 + $wordLast;
        $newLength = $dp[$state] + $length - ($currentLast === $wordFirst ? 1 : 0);
        if ($newLength < $next[$newState]) {
            $next[$newState] = $newLength;
        }

        // join(word, current string)
        $newState = $wordFirst * 26 + $currentLast;
        $newLength = $dp[$state] + $length - ($wordLast === $currentFirst ? 1 : 0);
        if ($newLength < $next[$newState]) {
            $next[$newState] = $newLength;
        }
    }

    $dp = $next;
}

echo min($dp) . PHP_EOL;
?>
