<?php

$input = stream_get_contents(STDIN);
preg_match_all('/\d+/', $input, $matches);
$values = array_map('intval', $matches[0]);

$low = $values[0];
$high = $values[1];
$k = $values[2];

function countBeautiful(int $limit, int $k): int
{
    if ($limit <= 0) {
        return 0;
    }

    $digits = array_map('intval', str_split((string)$limit));
    $length = count($digits);
    $memo = [];

    $dfs = function (
        int $position,
        int $remainder,
        int $balance,
        bool $started,
        bool $tight
    ) use (&$dfs, &$memo, $digits, $length, $k): int {
        if ($position === $length) {
            return ($started && $balance === 0 && $remainder === 0) ? 1 : 0;
        }

        $key = $position . '|' . $remainder . '|' . $balance . '|' .
               (int)$started . '|' . (int)$tight;

        if (isset($memo[$key])) {
            return $memo[$key];
        }

        $upper = $tight ? $digits[$position] : 9;
        $count = 0;

        for ($digit = 0; $digit <= $upper; $digit++) {
            $nextTight = $tight && ($digit === $upper);

            if (!$started && $digit === 0) {
                $count += $dfs(
                    $position + 1,
                    0,
                    0,
                    false,
                    $nextTight
                );
            } else {
                $nextBalance = $balance + (($digit % 2 === 0) ? 1 : -1);
                $nextRemainder = ($remainder * 10 + $digit) % $k;

                $count += $dfs(
                    $position + 1,
                    $nextRemainder,
                    $nextBalance,
                    true,
                    $nextTight
                );
            }
        }

        return $memo[$key] = $count;
    };

    return $dfs(0, 0, 0, false, true);
}

$result = countBeautiful($high, $k) - countBeautiful($low - 1, $k);
echo $result . PHP_EOL;
