<?php

$input = stream_get_contents(STDIN);
preg_match_all('/\d+/', $input, $matches);
$values = array_map('intval', $matches[0]);

if (count($values) < 2) {
    echo "-1\n";
    exit;
}

$target = array_pop($values);
$counts = array_fill(0, 64, 0);
$total = 0;

foreach ($values as $value) {
    $total += $value;
    $power = 0;

    while ($value > 1) {
        $value = intdiv($value, 2);
        $power++;
    }

    $counts[$power]++;
}

if ($total < $target) {
    echo "-1\n";
    exit;
}

$operations = 0;

for ($bit = 0; $bit <= 30; $bit++) {
    if ((($target >> $bit) & 1) === 1) {
        if ($counts[$bit] === 0) {
            $higher = $bit + 1;

            while ($higher < 64 && $counts[$higher] === 0) {
                $higher++;
            }

            if ($higher >= 64) {
                echo "-1\n";
                exit;
            }

            while ($higher > $bit) {
                $counts[$higher]--;
                $counts[$higher - 1] += 2;
                $operations++;
                $higher--;
            }
        }

        $counts[$bit]--;
    }

    $counts[$bit + 1] += intdiv($counts[$bit], 2);
    $counts[$bit] %= 2;
}

echo $operations . PHP_EOL;
?>
