<?php

const MOD = 12345;

$data = file_get_contents("php://stdin");
$length = strlen($data);
$index = 0;

function nextInt(string $data, int &$index, int $length): ?int
{
    while ($index < $length) {
        $ord = ord($data[$index]);
        if ($ord >= 48 && $ord <= 57) {
            break;
        }
        $index++;
    }

    if ($index >= $length) {
        return null;
    }

    $value = 0;
    while ($index < $length) {
        $ord = ord($data[$index]);
        if ($ord < 48 || $ord > 57) {
            break;
        }
        $value = $value * 10 + ($ord - 48);
        $index++;
    }

    return $value;
}

$n = nextInt($data, $index, $length);
$values = [];

while (($value = nextInt($data, $index, $length)) !== null) {
    $values[] = $value % MOD;
}

$total = count($values);
$m = intdiv($total, $n);

$result = [];
$product = 1;

for ($i = 0; $i < $total; $i++) {
    $result[$i] = $product;
    $product = ($product * $values[$i]) % MOD;
}

$product = 1;

for ($i = $total - 1; $i >= 0; $i--) {
    $result[$i] = ($result[$i] * $product) % MOD;
    $product = ($product * $values[$i]) % MOD;
}

$output = $n . "\n";

for ($row = 0; $row < $n; $row++) {
    $line = [];
    $offset = $row * $m;

    for ($col = 0; $col < $m; $col++) {
        $line[] = (string)$result[$offset + $col];
    }

    $output .= implode(' ', $line) . "\n";
}

echo $output;
