<?php

$input = trim(stream_get_contents(STDIN));
$lines = preg_split('/\R+/', $input);

$nums1 = array_map('intval', preg_split('/\s+/', trim($lines[0])));
$nums2 = array_map('intval', preg_split('/\s+/', trim($lines[1])));

$n = count($nums1);

function operationsNeeded(array $nums1, array $nums2, int $max1, int $max2, int $initial): int
{
    $count = $initial;
    $n = count($nums1);

    for ($i = 0; $i < $n - 1; $i++) {
        if ($nums1[$i] <= $max1 && $nums2[$i] <= $max2) {
            continue;
        }

        if ($nums2[$i] <= $max1 && $nums1[$i] <= $max2) {
            $count++;
        } else {
            return PHP_INT_MAX;
        }
    }

    return $count;
}

$last1 = $nums1[$n - 1];
$last2 = $nums2[$n - 1];

$withoutLastSwap = operationsNeeded($nums1, $nums2, $last1, $last2, 0);
$withLastSwap = operationsNeeded($nums1, $nums2, $last2, $last1, 1);

$answer = min($withoutLastSwap, $withLastSwap);

echo $answer === PHP_INT_MAX ? -1 : $answer;
?>
