$n = strlen($word);

function countInSegment(string $word, int $start, int $end, int $k): int
{
    $length = $end - $start;
    $maxDistinct = min(26, intdiv($length, $k));
    $result = 0;

    for ($distinct = 1; $distinct <= $maxDistinct; $distinct++) {
        $windowLength = $distinct * $k;
        $counts = array_fill(0, 26, 0);
        $exactK = 0;

        for ($i = $start; $i < $start + $windowLength; $i++) {
            $index = ord($word[$i]) - 97;
            $oldCount = $counts[$index];

            if ($oldCount === $k) {
                $exactK--;
            }

            $counts[$index] = $oldCount + 1;

            if ($counts[$index] === $k) {
                $exactK++;
            }
        }

        if ($exactK === $distinct) {
            $result++;
        }

        $lastWindowStart = $end - $windowLength;

        for ($windowStart = $start + 1; $windowStart <= $lastWindowStart; $windowStart++) {
            $outIndex = ord($word[$windowStart - 1]) - 97;
            $oldCount = $counts[$outIndex];

            if ($oldCount === $k) {
                $exactK--;
            }

            $counts[$outIndex] = $oldCount - 1;

            if ($counts[$outIndex] === $k) {
                $exactK++;
            }

            $inIndex = ord($word[$windowStart + $windowLength - 1]) - 97;
            $oldCount = $counts[$inIndex];

            if ($oldCount === $k) {
                $exactK--;
            }

            $counts[$inIndex] = $oldCount + 1;

            if ($counts[$inIndex] === $k) {
                $exactK++;
            }

            if ($exactK === $distinct) {
                $result++;
            }
        }
    }

    return $result;
}

$answer = 0;
$segmentStart = 0;

for ($i = 1; $i < $n; $i++) {
    if (abs(ord($word[$i]) - ord($word[$i - 1])) > 2) {
        $answer += countInSegment($word, $segmentStart, $i, $k);
        $segmentStart = $i;
    }
}

$answer += countInSegment($word, $segmentStart, $n, $k);

echo $answer, PHP_EOL;
