        // Decrement to the nearest lower multiple, then divide.
        $lower = intdiv($value, $divisor);
        $best = min($best, $remainder + 1 + $solve($lower));

        // Increment to the nearest higher multiple, then divide.
        if ($remainder !== 0) {
            $increments = $divisor - $remainder;
            $upper = intdiv($value + $increments, $divisor);
            $best = min($best, $increments + 1 + $solve($upper));
        }
    }

    return $memo[$value] = $best;
};

