```php
<?php

final class FastScanner
{
    private string $data;
    private int $index = 0;
    private int $length;

    public function __construct()
    {
        $this->data = file_get_contents("php://stdin");
        $this->length = strlen($this->data);
    }

    public function nextInt(): int
    {
        while ($this->index < $this->length && ord($this->data[$this->index]) <= 32) {
            $this->index++;
        }

        $sign = 1;
        if ($this->index < $this->length && $this->data[$this->index] === '-') {
            $sign = -1;
            $this->index++;
        }

        $number = 0;
        while ($this->index < $this->length) {
            $code = ord($this->data[$this->index]);
            if ($code < 48 || $code > 57) {
                break;
            }
            $number = $number * 10 + ($code - 48);
            $this->index++;
        }

        return $number * $sign;
    }
}

function farthestNode(
    int $start,
    array &$head,
    array &$to,
    array &$next
): array {
    $nodeCount = count($head);
    $distance = array_fill(0, $nodeCount, -1);
    $queue = [];

    $queueHead = 0;
    $queueTail = 0;
    $queue[$queueTail++] = $start;
    $distance[$start] = 0;

    $farthest = $start;
    $maxDistance = 0;

    while ($queueHead < $queueTail) {
        $node = $queue[$queueHead++];
        $currentDistance = $distance[$node];

        if ($currentDistance > $maxDistance) {
            $maxDistance = $currentDistance;
            $farthest = $node;
        }

        for ($edge = $head[$node]; $edge !== -1; $edge = $next[$edge]) {
            $neighbor = $to[$edge];
            if ($distance[$neighbor] === -1) {
                $distance[$neighbor] = $currentDistance + 1;
                $queue[$queueTail++] = $neighbor;
            }
        }
    }

    return [$farthest, $maxDistance];
}

function readTreeDiameter(FastScanner $scanner): int
{
    $edgeCount = $scanner->nextInt();
    $nodeCount = $edgeCount + 1;

    $head = array_fill(0, $nodeCount, -1);
    $to = [];
    $next = [];
    $edgeIndex = 0;

    for ($i = 0; $i < $edgeCount; $i++) {
        $a = $scanner->nextInt();
        $b = $scanner->nextInt();

        $to[$edgeIndex] = $b;
        $next[$edgeIndex] = $head[$a];
        $head[$a] = $edgeIndex++;

        $to[$edgeIndex] = $a;
        $next[$edgeIndex] = $head[$b];
        $head[$b] = $edgeIndex++;
    }

    [$endpoint] = farthestNode(0, $head, $to, $next);
    [, $diameter] = farthestNode($endpoint, $head, $to, $next);

    return $diameter;
}

$scanner = new FastScanner();

$diameter1 = readTreeDiameter($scanner);
$diameter2 = readTreeDiameter($scanner);

$radius1 = intdiv($diameter1 + 1, 2);
$radius2 = intdiv($diameter2 + 1, 2);

$result = max(
    $diameter1,
    $diameter2,
    $radius1 + $radius2 + 1
);

echo $result, PHP_EOL;
