<?php

final class DisjointSet
{
    private array $parent;
    private array $size;

    public function __construct(int $n)
    {
        $this->parent = range(0, $n - 1);
        $this->size = array_fill(0, $n, 1);
    }

    public function find(int $x): int
    {
        $root = $x;
        while ($this->parent[$root] !== $root) {
            $root = $this->parent[$root];
        }

        while ($this->parent[$x] !== $x) {
            $next = $this->parent[$x];
            $this->parent[$x] = $root;
            $x = $next;
        }

        return $root;
    }

    public function union(int $a, int $b): void
    {
        $rootA = $this->find($a);
        $rootB = $this->find($b);

        if ($rootA === $rootB) {
            return;
        }

        if ($this->size[$rootA] < $this->size[$rootB]) {
            [$rootA, $rootB] = [$rootB, $rootA];
        }

        $this->parent[$rootB] = $rootA;
        $this->size[$rootA] += $this->size[$rootB];
    }

    public function connected(int $a, int $b): bool
    {
        return $this->find($a) === $this->find($b);
    }
}

$input = trim(stream_get_contents(STDIN));
$tokens = preg_split('/\s+/', $input);
$index = 0;

$xCorner = (int)$tokens[$index++];
$yCorner = (int)$tokens[$index++];
$n = (int)$tokens[$index++];

$circles = [];
for ($i = 0; $i < $n; $i++) {
    $circles[] = [
        (int)$tokens[$index++],
        (int)$tokens[$index++],
        (int)$tokens[$index++]
    ];
}

$sideA = $n;     // Left and top sides
$sideB = $n + 1; // Bottom and right sides
$dsu = new DisjointSet($n + 2);

for ($i = 0; $i < $n; $i++) {
    [$x, $y, $r] = $circles[$i];
    $rSquared = $r * $r;

    // The starting or ending corner may not touch or lie inside a circle.
    $startDistanceSquared = $x * $x + $y * $y;
    $endDx = $x - $xCorner;
    $endDy = $y - $yCorner;
    $endDistanceSquared = $endDx * $endDx + $endDy * $endDy;

    if ($startDistanceSquared <= $rSquared || $endDistanceSquared <= $rSquared) {
        echo "false\n";
        exit;
    }

    // Distance to the left side segment.
    $leftDy = max(0, $y - $yCorner);
    $touchesLeft = $x * $x + $leftDy * $leftDy <= $rSquared;

    // Distance to the top side segment.
    $topDx = max(0, $x - $xCorner);
    $topDy = $y - $yCorner;
    $touchesTop = $topDx * $topDx + $topDy * $topDy <= $rSquared;

    // Distance to the bottom side segment.
    $bottomDx = max(0, $x - $xCorner);
    $touchesBottom = $bottomDx * $bottomDx + $y * $y <= $rSquared;

    // Distance to the right side segment.
    $rightDx = $x - $xCorner;
    $rightDy = max(0, $y - $yCorner);
    $touchesRight = $rightDx * $rightDx + $rightDy * $rightDy <= $rSquared;

    if ($touchesLeft || $touchesTop) {
        $dsu->union($i, $sideA);
    }
    if ($touchesBottom || $touchesRight) {
        $dsu->union($i, $sideB);
    }

    if ($dsu->connected($sideA, $sideB)) {
        echo "false\n";
        exit;
    }
}

for ($i = 0; $i < $n; $i++) {
    [$x1, $y1, $r1] = $circles[$i];

    for ($j = $i + 1; $j < $n; $j++) {
        [$x2, $y2, $r2] = $circles[$j];

        $dx = $x1 - $x2;
        $dy = $y1 - $y2;
        $radiusSum = $r1 + $r2;

        if ($dx * $dx + $dy * $dy > $radiusSum * $radiusSum) {
            continue;
        }

        // A point in both circles, dividing their centers in proportion
        // to their radii, must lie in the rectangle's interior.
        $weightedX = $x1 * $r2 + $x2 * $r1;
        $weightedY = $y1 * $r2 + $y2 * $r1;

        if (
            $weightedX < $radiusSum * $xCorner &&
            $weightedY < $radiusSum * $yCorner
        ) {
            $dsu->union($i, $j);

            if ($dsu->connected($sideA, $sideB)) {
                echo "false\n";
                exit;
            }
        }
    }
}

echo "true\n";
