$s = trim(stream_get_contents(STDIN));
$n = strlen($s);

$zeroPositions = [-1];

for ($i = 0; $i < $n; $i++) {
    if ($s[$i] === '0') {
        $zeroPositions[] = $i;
    }
}

$zeroCount = count($zeroPositions) - 1;
$zeroPositions[] = $n;

$answer = 0;

// Substrings containing no zeros.
for ($i = 1; $i <= $zeroCount + 1; $i++) {
    $runLength = $zeroPositions[$i] - $zeroPositions[$i - 1] - 1;
    $answer += (($runLength * ($runLength + 1)) >> 1);
}

// A valid substring with k zeros must have length at least k^2 + k.
$maxZeros = (int) floor((sqrt(1 + 4 * $n) - 1) / 2);
$maxZeros = min($maxZeros, $zeroCount);

for ($k = 1; $k <= $maxZeros; $k++) {
    $requiredLength = $k * $k + $k;
    $lastStartIndex = $zeroCount - $k + 1;

    for ($i = 1; $i <= $lastStartIndex; $i++) {
        $firstZero = $zeroPositions[$i];
        $lastZero = $zeroPositions[$i + $k - 1];

        $leftChoices = $firstZero - $zeroPositions[$i - 1];
        $rightChoices = $zeroPositions[$i + $k] - $lastZero;

        $baseLength = $lastZero - $firstZero + 1;
        $neededExtension = $requiredLength - $baseLength;
        $totalChoices = $leftChoices * $rightChoices;

        if ($neededExtension <= 0) {
            $answer += $totalChoices;
            continue;
        }

        $maxExtension = $leftChoices + $rightChoices - 2;
        if ($neededExtension > $maxExtension) {
            continue;
        }

        // Count extension pairs (x, y) with x + y < neededExtension.
        $q = $neededExtension - 1;
        $invalid = ((($q + 1) * ($q + 2)) >> 1);

        if ($q >= $leftChoices) {
            $v = $q - $leftChoices;
            $invalid -= ((($v + 1) * ($v + 2)) >> 1);
        }

        if ($q >= $rightChoices) {
            $v = $q - $rightChoices;
            $invalid -= ((($v + 1) * ($v + 2)) >> 1);
        }

        $answer += $totalChoices - $invalid;
    }
}

echo $answer, PHP_EOL;
