<?php

class FastScanner
{
    private $data;
    private $length;
    private $index = 0;

    public function __construct()
    {
        $this->data = file_get_contents('php://stdin');
        $this->length = strlen($this->data);
    }

    public function nextInt()
    {
        while ($this->index < $this->length) {
            $c = ord($this->data[$this->index]);
            if ($c > 32) {
                break;
            }
            $this->index++;
        }

        $sign = 1;
        if ($this->index < $this->length && $this->data[$this->index] === '-') {
            $sign = -1;
            $this->index++;
        }

        $number = 0;
        while ($this->index < $this->length) {
            $c = ord($this->data[$this->index]);
            if ($c < 48 || $c > 57) {
                break;
            }
            $number = $number * 10 + ($c - 48);
            $this->index++;
        }

        return $number * $sign;
    }
}

function longestIncreasingChain(&$points, $base, $maxCoordinate)
{
    if (count($points) === 0) {
        return 0;
    }

    sort($points);

    $tails = [];
    $length = 0;

    foreach ($points as $encoded) {
        $reversedY = $encoded % $base;
        $y = $maxCoordinate - $reversedY;

        $left = 0;
        $right = $length;

        while ($left < $right) {
            $middle = intdiv($left + $right, 2);
            if ($tails[$middle] < $y) {
                $left = $middle + 1;
            } else {
                $right = $middle;
            }
        }

        if ($left === $length) {
            $tails[] = $y;
            $length++;
        } else {
            $tails[$left] = $y;
        }
    }

    return $length;
}

$scanner = new FastScanner();
$n = $scanner->nextInt();

$base = 1000000001;
$maxCoordinate = 1000000000;
$coordinates = [];

for ($i = 0; $i < $n; $i++) {
    $x = $scanner->nextInt();
    $y = $scanner->nextInt();
    $coordinates[] = $x * $base + $y;
}

$k = $scanner->nextInt();

$target = $coordinates[$k];
$targetX = intdiv($target, $base);
$targetY = $target % $base;

$southwest = [];
$northeast = [];

foreach ($coordinates as $encoded) {
    $x = intdiv($encoded, $base);
    $y = $encoded % $base;

    if ($x < $targetX && $y < $targetY) {
        $southwest[] = $x * $base + ($maxCoordinate - $y);
    } elseif ($x > $targetX && $y > $targetY) {
        $northeast[] = $x * $base + ($maxCoordinate - $y);
    }
}

$answer = 1
    + longestIncreasingChain($southwest, $base, $maxCoordinate)
    + longestIncreasingChain($northeast, $base, $maxCoordinate);

echo $answer, PHP_EOL;
?>
