function buildGraph(array $pairs, array $rates): array
{
    $graph = [];

    foreach ($pairs as $i => [$from, $to]) {
        $rate = $rates[$i];
        $graph[$from][] = [$to, $rate];
        $graph[$to][] = [$from, 1.0 / $rate];
    }

    return $graph;
}

function calculateAmounts(string $start, array $graph): array
{
    $amounts = [$start => 1.0];
    $stack = [$start];

    while ($stack) {
        $currency = array_pop($stack);

        foreach ($graph[$currency] ?? [] as [$nextCurrency, $rate]) {
            if (!array_key_exists($nextCurrency, $amounts)) {
                $amounts[$nextCurrency] = $amounts[$currency] * $rate;
                $stack[] = $nextCurrency;
            }
        }
    }

    return $amounts;
}

