$dist = array_fill(0, $totalRooms, PHP_INT_MAX);
$dist[0] = 0;

$queue = new SplPriorityQueue();
$queue->setExtractFlags(SplPriorityQueue::EXTR_BOTH);
$queue->insert(0, 0);

$directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
$target = $totalRooms - 1;

while (!$queue->isEmpty()) {
    $entry = $queue->extract();
    $id = $entry['data'];
    $time = -(int) $entry['priority'];

    if ($time !== $dist[$id]) {
        continue;
    }

    if ($id === $target) {
        echo $time . PHP_EOL;
        exit;
    }

    $row = intdiv($id, $m);
    $col = $id % $m;

    foreach ($directions as [$dr, $dc]) {
        $nextRow = $row + $dr;
        $nextCol = $col + $dc;

        if ($nextRow < 0 || $nextRow >= $n || $nextCol < 0 || $nextCol >= $m) {
            continue;
        }

        $nextId = $nextRow * $m + $nextCol;
        $arrivalTime = max($time, $moveTime[$nextRow][$nextCol]) + 1;

        if ($arrivalTime < $dist[$nextId]) {
            $dist[$nextId] = $arrivalTime;
            $queue->insert($nextId, -$arrivalTime);
