        $position++;
    }

    return $number;
}

$input = file_get_contents('php://stdin');
$inputLength = strlen($input);

$lineEnd = strpos($input, "\n");
if ($lineEnd === false) {
    echo "-1\n";
    exit;
}

$nums = parseIntegerLine(substr($input, 0, $lineEnd));
$n = count($nums);
$position = $lineEnd + 1;

$queryCount = nextInteger($input, $position, $inputLength);

$head = array_fill(0, $n, -1);
$right = [];
$next = [];

for ($i = 0; $i < $queryCount; $i++) {
    $leftEndpoint = nextInteger($input, $position, $inputLength);
    $rightEndpoint = nextInteger($input, $position, $inputLength);

    $right[] = $rightEndpoint;
    $next[] = $head[$leftEndpoint];
    $head[$leftEndpoint] = $i;
}

$expiration = array_fill(0, $n + 1, 0);
$available = new SplPriorityQueue();
$available->setExtractFlags(SplPriorityQueue::EXTR_DATA);

$activeQueries = 0;
$usedQueries = 0;

for ($index = 0; $index < $n; $index++) {
    $activeQueries += $expiration[$index];

    for ($query = $head[$index]; $query !== -1; $query = $next[$query]) {
        $endpoint = $right[$query];
        $available->insert($endpoint, $endpoint);
    }

    while ($activeQueries < $nums[$index]) {
        if ($available->isEmpty()) {
            echo "-1\n";
            exit;
        }

        $endpoint = $available->top();

        if ($endpoint < $index) {
            echo "-1\n";
            exit;
        }

        $available->extract();
        $activeQueries++;
        $usedQueries++;
        $expiration[$endpoint + 1]--;
    }
}

echo ($queryCount - $usedQueries) . "\n";
