<?php

final class FastScanner
{
    private string $data;
    private int $index = 0;
    private int $length;

    public function __construct()
    {
        $this->data = file_get_contents('php://stdin');
        $this->length = strlen($this->data);
    }

    public function nextInt(): int
    {
        while ($this->index < $this->length) {
            $code = ord($this->data[$this->index]);
            if (($code >= 48 && $code <= 57) || $code === 45) {
                break;
            }
            $this->index++;
        }

        $sign = 1;
        if ($this->index < $this->length && $this->data[$this->index] === '-') {
            $sign = -1;
            $this->index++;
        }

        $number = 0;
        while ($this->index < $this->length) {
            $code = ord($this->data[$this->index]);
            if ($code < 48 || $code > 57) {
                break;
            }
            $number = $number * 10 + ($code - 48);
            $this->index++;
        }

        return $number * $sign;
    }
}

function prefixCoins(
    int $position,
    array &$left,
    array &$right,
    array &$value,
    array &$prefix,
    int $n
): int {
    $low = 0;
    $high = $n;

    while ($low < $high) {
        $mid = ($low + $high) >> 1;
        if ($left[$mid] <= $position) {
            $low = $mid + 1;
        } else {
            $high = $mid;
        }
    }

    if ($low === 0) {
        return 0;
    }

    $index = $low - 1;
    $sum = $prefix[$index];

    $coveredEnd = min($position, $right[$index]);
    if ($coveredEnd >= $left[$index]) {
        $sum += ($coveredEnd - $left[$index] + 1) * $value[$index];
    }

    return $sum;
}

$scanner = new FastScanner();
$n = $scanner->nextInt();

$left = [];
$right = [];
$value = [];

for ($i = 0; $i < $n; $i++) {
    $left[] = $scanner->nextInt();
    $right[] = $scanner->nextInt();
    $value[] = $scanner->nextInt();
}

$k = $scanner->nextInt();

array_multisort(
    $left, SORT_ASC, SORT_NUMERIC,
    $right, SORT_ASC, SORT_NUMERIC,
    $value, SORT_ASC, SORT_NUMERIC
);

$prefix = array_fill(0, $n + 1, 0);
for ($i = 0; $i < $n; $i++) {
    $length = $right[$i] - $left[$i] + 1;
    $prefix[$i + 1] = $prefix[$i] + $length * $value[$i];
}

$answer = 0;

for ($i = 0; $i < $n; $i++) {
    $start = $left[$i];
    $sum = prefixCoins($start + $k - 1, $left, $right, $value, $prefix, $n)
         - prefixCoins($start - 1, $left, $right, $value, $prefix, $n);
    if ($sum > $answer) {
        $answer = $sum;
    }

    $start = $right[$i] - $k + 1;
    $sum = prefixCoins($start + $k - 1, $left, $right, $value, $prefix, $n)
         - prefixCoins($start - 1, $left, $right, $value, $prefix, $n);
    if ($sum > $answer) {
        $answer = $sum;
    }
}

echo $answer, PHP_EOL;
