function findSection(array &$cuts, int $count, int $coordinate): int
{
    $left = 0;
    $right = $count;

    while ($left < $right) {
        $mid = intdiv($left + $right, 2);
        if ($cuts[$mid] < $coordinate) {
            $left = $mid + 1;
        } else {
            $right = $mid;
        }
    }

    return $left;
}

