$maxSkips = min(28, $n - 2);
$ringSize = $maxSkips + 2;
$inf = PHP_FLOAT_MAX;

$initial = array_fill(0, $maxSkips + 1, $inf);
$initial[0] = 0.0;

$dpRing = array_fill(0, $ringSize, null);
$dpRing[0] = $initial;
$finalDp = $initial;

for ($i = 1; $i < $n; $i++) {
    $current = array_fill(0, $maxSkips + 1, $inf);
    $maxDirectSkips = min($maxSkips, $i - 1);

    for ($directSkips = 0; $directSkips <= $maxDirectSkips; $directSkips++) {
        $previous = $i - $directSkips - 1;
        $previousDp = $dpRing[$previous % $ringSize];

        $dx = $x[$i] - $x[$previous];
        $dy = $y[$i] - $y[$previous];
        $distance = sqrt($dx * $dx + $dy * $dy);

        $maxPreviousSkips = min(
            $maxSkips - $directSkips,
            max(0, $previous - 1)
        );

        for ($oldSkips = 0; $oldSkips <= $maxPreviousSkips; $oldSkips++) {
            $totalSkips = $oldSkips + $directSkips;
            $candidate = $previousDp[$oldSkips] + $distance;

            if ($candidate < $current[$totalSkips]) {
                $current[$totalSkips] = $candidate;
            }
        }
    }

    $dpRing[$i % $ringSize] = $current;
    $finalDp = $current;
