        $weights[$j][$i] = $weight;
    }
}

// Add a zero-weight dummy vertex when N is odd.
if ($n % 2 === 1) {
    for ($i = 0; $i < $n; $i++) {
        $weights[$i][] = 0;
    }
    $weights[] = array_fill(0, $n + 1, 0);
    $n++;
}

$size = 1 << $n;
$fullMask = $size - 1;
$dp = array_fill(0, $size, -1);
$dp[0] = 0;

for ($mask = 0; $mask < $fullMask; $mask++) {
    if ($dp[$mask] < 0) {
        continue;
    }

    $first = -1;
    for ($i = 0; $i < $n; $i++) {
        if (($mask & (1 << $i)) === 0) {
            $first = $i;
            break;
        }
    }

    if ($first === -1) {
        continue;
    }

    $firstBit = 1 << $first;

    for ($j = $first + 1; $j < $n; $j++) {
        $secondBit = 1 << $j;
        if (($mask & $secondBit) !== 0) {
            continue;
        }

        $newMask = $mask | $firstBit | $secondBit;
        $candidate = $dp[$mask] + $weights[$first][$j];

        if ($candidate > $dp[$newMask]) {
            $dp[$newMask] = $candidate;
        }
    }
}

echo $dp[$fullMask], PHP_EOL;
