$input = file_get_contents('php://stdin');
$inputLength = strlen($input);
$position = 0;

function nextInt(): int
{
    global $input, $inputLength, $position;

    while ($position < $inputLength) {
        $c = ord($input[$position]);
        if ($c >= 48 && $c <= 57) {
            break;
        }
        $position++;
    }

    $number = 0;
    while ($position < $inputLength) {
        $c = ord($input[$position]);
        if ($c < 48 || $c > 57) {
            break;
        }
        $number = $number * 10 + ($c - 48);
        $position++;
    }

    return $number;
}

function findRoot(int $vertex, array &$parent): int
{
    $root = $vertex;
    while ($parent[$root] !== $root) {
        $root = $parent[$root];
    }

    while ($parent[$vertex] !== $vertex) {
        $next = $parent[$vertex];
        $parent[$vertex] = $root;
        $vertex = $next;
    }

    return $root;
}

$n = nextInt();

$parent = range(0, $n);
$componentSize = array_fill(0, $n + 1, 1);
$componentSize[0] = 0;
$neighborsOfOne = [];

for ($i = 0; $i < $n - 1; $i++) {
    $u = nextInt();
    $v = nextInt();

    if ($u === 1) {
        $neighborsOfOne[] = $v;
        continue;
    }
    if ($v === 1) {
        $neighborsOfOne[] = $u;
        continue;
    }

    $rootU = findRoot($u, $parent);
    $rootV = findRoot($v, $parent);

    if ($rootU === $rootV) {
        continue;
    }

    if ($componentSize[$rootU] < $componentSize[$rootV]) {
        [$rootU, $rootV] = [$rootV, $rootU];
    }

    $parent[$rootV] = $rootU;
    $componentSize[$rootU] += $componentSize[$rootV];
}

$largestBranch = 0;

foreach ($neighborsOfOne as $neighbor) {
    $root = findRoot($neighbor, $parent);
    if ($componentSize[$root] > $largestBranch) {
        $largestBranch = $componentSize[$root];
    }
}

echo ($n - $largestBranch), PHP_EOL;
