```php
<?php

const MOD = 998244353;

function modPow(int $base, int $exp): int
{
    $result = 1;
    while ($exp > 0) {
        if ($exp & 1) {
            $result = ($result * $base) % MOD;
        }
        $base = ($base * $base) % MOD;
        $exp >>= 1;
    }
    return $result;
}

$input = trim(stream_get_contents(STDIN));
$values = preg_split('/\s+/', $input);
$pos = 0;

$K = (int)$values[$pos++];
$limits = [];
for ($i = 0; $i < 26; ++$i) {
    $limits[] = (int)$values[$pos++];
}

$factorial = array_fill(0, $K + 1, 1);
$inverseFactorial = array_fill(0, $K + 1, 1);

for ($i = 1; $i <= $K; ++$i) {
    $factorial[$i] = ($factorial[$i - 1] * $i) % MOD;
}

$inverseFactorial[$K] = modPow($factorial[$K], MOD - 2);
for ($i = $K; $i >= 1; --$i) {
    $inverseFactorial[$i - 1] = ($inverseFactorial[$i] * $i) % MOD;
}

$dp = array_fill(0, $K + 1, 0);
$dp[0] = 1;
$currentMax = 0;

foreach ($limits as $limit) {
    $limit = min($limit, $K);
    if ($limit === 0) {
        continue;
    }

    $next = array_fill(0, $K + 1, 0);

    for ($used = 0; $used <= $currentMax; ++$used) {
        $value = $dp[$used];
        if ($value === 0) {
            continue;
        }

        $maxAdd = min($limit, $K - $used);
        for ($add = 0; $add <= $maxAdd; ++$add) {
            $index = $used + $add;
            $next[$index] = (
                $next[$index] + $value * $inverseFactorial[$add]
            ) % MOD;
        }
    }

    $dp = $next;
    $currentMax = min($K, $currentMax + $limit);
}

$answer = 0;
for ($length = 1; $length <= $currentMax; ++$length) {
    $answer = (
        $answer + $dp[$length] * $factorial[$length]
    ) % MOD;
}

echo $answer, PHP_EOL;
