function nextInt(): int
{
    global $input, $inputLength, $inputPosition;

    while ($inputPosition < $inputLength && ord($input[$inputPosition]) <= 32) {
        $inputPosition++;
    }

    $sign = 1;
    if ($inputPosition < $inputLength && $input[$inputPosition] === '-') {
        $sign = -1;
        $inputPosition++;
    }

    $value = 0;
    while ($inputPosition < $inputLength) {
        $code = ord($input[$inputPosition]);
        if ($code < 48 || $code > 57) {
            break;
        }
        $value = $value * 10 + ($code - 48);
        $inputPosition++;
    }

    return $value * $sign;
}

function lowerBound(array &$values, int $target): int
{
    $left = 0;
    $right = count($values);

    while ($left < $right) {
        $middle = intdiv($left + $right, 2);
        if ($values[$middle] < $target) {
            $left = $middle + 1;
        } else {
            $right = $middle;
        }
    }

    return $left;
}

function upperBound(array &$values, int $target): int
{
    $left = 0;
    $right = count($values);

    while ($left < $right) {
        $middle = intdiv($left + $right, 2);
        if ($values[$middle] <= $target) {
            $left = $middle + 1;
        } else {
            $right = $middle;
        }
    }

    return $left;
}

function getMedianAndMinimumCost(array &$values, int $n): array
{
    $center = $values[intdiv($n - 1, 2)];
    $cost = 0;

    for ($i = 0; $i < $n; $i++) {
        $difference = $values[$i] - $center;
        if ($difference < 0) {
            $difference = -$difference;
        }
        $cost += $difference;
    }

    return [$center, $cost];
}

function buildCumulativeCounts(
    array &$values,
    int $n,
    int $center,
    int $minimumCost,
    int $slack
): array {
    $counts = array_fill(0, $slack + 1, 0);
    $counts[0] = 1;

    // Enumerate positions to the right of the lower median.
    $x = $center;
    $cost = $minimumCost;
    $countLessOrEqual = upperBound($values, $center);

    while (true) {
        $nextCost = $cost + 2 * $countLessOrEqual - $n;
        $x++;

        $excess = $nextCost - $minimumCost;
        if ($excess > $slack) {
            break;
        }

        $counts[$excess]++;
        $cost = $nextCost;

        while ($countLessOrEqual < $n && $values[$countLessOrEqual] <= $x) {
            $countLessOrEqual++;
        }
    }

    // Enumerate positions to the left of the lower median.
    $x = $center;
    $cost = $minimumCost;
    $countLess = lowerBound($values, $center);

    while (true) {
        $nextCost = $cost + $n - 2 * $countLess;
        $x--;

        $excess = $nextCost - $minimumCost;
        if ($excess > $slack) {
            break;
        }

        $counts[$excess]++;
        $cost = $nextCost;

        while ($countLess > 0 && $values[$countLess - 1] >= $x) {
            $countLess--;
        }
    }

    for ($i = 1; $i <= $slack; $i++) {
        $counts[$i] += $counts[$i - 1];
    }

    return $counts;
}

function countPairsUsingOtherDimension(
    array &$values,
    array &$cumulativeCounts,
    int $n,
    int $center,
    int $minimumCost,
    int $slack
): int {
    $answer = $cumulativeCounts[$slack];

    // Enumerate positions to the right.
    $x = $center;
    $cost = $minimumCost;
    $countLessOrEqual = upperBound($values, $center);

    while (true) {
        $nextCost = $cost + 2 * $countLessOrEqual - $n;
        $x++;

        $excess = $nextCost - $minimumCost;
        if ($excess > $slack) {
            break;
        }

        $answer += $cumulativeCounts[$slack - $excess];
        $cost = $nextCost;

        while ($countLessOrEqual < $n && $values[$countLessOrEqual] <= $x) {
            $countLessOrEqual++;
        }
    }

    // Enumerate positions to the left.
    $x = $center;
    $cost = $minimumCost;
    $countLess = lowerBound($values, $center);

    while (true) {
        $nextCost = $cost + $n - 2 * $countLess;
        $x--;

        $excess = $nextCost - $minimumCost;
        if ($excess > $slack) {
            break;
        }

        $answer += $cumulativeCounts[$slack - $excess];
        $cost = $nextCost;

        while ($countLess > 0 && $values[$countLess - 1] >= $x) {
            $countLess--;
        }
    }

    return $answer;
}

