        $answer = $currentCost;
        return;
    }

    for ($vertex = 0; $vertex < $n; $vertex++) {
        if ($used[$vertex]) {
            continue;
        }

        $additionalCost = 0;
        for ($previous = 0; $previous < $depth; $previous++) {
            $mappedPrevious = $permutation[$previous];
            if ($g[$previous][$depth] !== $h[$mappedPrevious][$vertex]) {
                $additionalCost += $cost[$mappedPrevious][$vertex];
            }
        }

        if ($currentCost + $additionalCost >= $answer) {
            continue;
        }

        $permutation[$depth] = $vertex;
        $used[$vertex] = true;
