final class FastScanner
{
    private string $data;
    private int $length;
    private int $position = 0;

    public function __construct()
    {
        $this->data = file_get_contents('php://stdin');
        $this->length = strlen($this->data);
    }

    public function nextInt(): int
    {
        while ($this->position < $this->length) {
            $c = ord($this->data[$this->position]);
            if ($c > 32) {
                break;
            }
            ++$this->position;
        }

        $number = 0;
        while ($this->position < $this->length) {
            $c = ord($this->data[$this->position]);
            if ($c < 48 || $c > 57) {
                break;
            }
            $number = $number * 10 + ($c - 48);
            ++$this->position;
        }

        return $number;
    }
}

$scanner = new FastScanner();
$testCases = $scanner->nextInt();
$answers = [];

for ($case = 0; $case < $testCases; ++$case) {
    $n = $scanner->nextInt();
    $k = $scanner->nextInt();

    $a = [];
    $b = [];

    for ($i = 0; $i < $n; ++$i) {
        $a[] = $scanner->nextInt();
    }
    for ($i = 0; $i < $n; ++$i) {
        $b[] = $scanner->nextInt();
    }

    array_multisort($a, SORT_ASC, SORT_NUMERIC, $b, SORT_ASC, SORT_NUMERIC);

    $heap = new SplPriorityQueue();
    $heap->setExtractFlags(SplPriorityQueue::EXTR_DATA);

    $sum = 0;
    $answer = PHP_INT_MAX;

    for ($i = 0; $i < $n; ++$i) {
        $value = $b[$i];
        $heap->insert($value, $value);
        $sum += $value;

        if ($heap->count() > $k) {
            $sum -= $heap->extract();
        }

        if ($heap->count() === $k) {
            $candidate = $a[$i] * $sum;
            if ($candidate < $answer) {
                $answer = $candidate;
            }
        }
    }

    $answers[] = (string)$answer;
}

echo implode("\n", $answers);
