        if ($forced[$j] !== 0 && $forced[$j] !== $requiredJ) {
            echo "0\n";
            exit;
        }
        if ($forced[$i] !== 0 && $forced[$i] !== $requiredI) {
            echo "0\n";
            exit;
        }

        $forced[$j] = $requiredJ;
        $forced[$i] = $requiredI;
    }
}

$free = 0;
for ($i = 0; $i < $Q; $i++) {
    if ($forced[$i] === 0) {
        $free++;
    }
