<?php

$input = trim(stream_get_contents(STDIN));
$tokens = preg_split('/\s+/', $input);
$pos = 0;

$n = intval($tokens[$pos++]);
$offsets = [];
for ($i = 0; $i < $n; $i++) {
    $offsets[] = intval($tokens[$pos++]);
}

/*
 * A crease x is a mountain fold exactly when
 * x ≡ 3 * 2^t (mod 2^(t+2))
 * for some t >= 0.
 *
 * Each such congruence for x = i + A becomes a prefix in a
 * binary trie whose bits are stored from least significant to most.
 */

$child0 = [-1];
$child1 = [-1];
$tag = [0];
$parent = [-1];
$nodeCount = 1;

foreach ($offsets as $a) {
    // t = 99 cannot be a mountain fold among positions below 2^100.
    for ($t = 0; $t <= 98; $t++) {
        $node = 0;
        $borrow = 0;
        $length = $t + 2;

        // Compute (3 * 2^t - A) modulo 2^(t+2), bit by bit.
        for ($bitPos = 0; $bitPos < $length; $bitPos++) {
            $xBit = ($bitPos === $t || $bitPos === $t + 1) ? 1 : 0;
            $aBit = ($bitPos < 60) ? (($a >> $bitPos) & 1) : 0;

            $value = $xBit - $aBit - $borrow;
            if ($value < 0) {
                $bit = $value + 2;
                $borrow = 1;
            } else {
                $bit = $value;
                $borrow = 0;
            }

            if ($bit === 0) {
                $next = $child0[$node];
                if ($next === -1) {
                    $next = $nodeCount++;
                    $child0[$node] = $next;
                    $child0[$next] = -1;
                    $child1[$next] = -1;
                    $tag[$next] = 0;
                    $parent[$next] = $node;
                }
            } else {
                $next = $child1[$node];
                if ($next === -1) {
                    $next = $nodeCount++;
                    $child1[$node] = $next;
                    $child0[$next] = -1;
                    $child1[$next] = -1;
                    $tag[$next] = 0;
                    $parent[$next] = $node;
                }
            }

            $node = $next;
        }

        $tag[$node]++;
    }
}

unset($child0, $child1);

$parent[0] = $tag[0];
$answer = $tag[0];

for ($i = 1; $i < $nodeCount; $i++) {
    $p = $parent[$i];
    $score = $parent[$p] + $tag[$i];
    $parent[$i] = $score;

    if ($score > $answer) {
        $answer = $score;
    }
}

echo $answer, PHP_EOL;
