<?php

const MOD = 998244353;

function polyTrim(array $a): array
{
    while (count($a) > 1 && $a[count($a) - 1] === 0) {
        array_pop($a);
    }
    return $a;
}

function polyMultiply(array $a, array $b, int $limit): array
{
    if ((count($a) === 1 && $a[0] === 0) ||
        (count($b) === 1 && $b[0] === 0)) {
        return [0];
    }

    $maxDegree = min($limit, count($a) + count($b) - 2);
    $result = array_fill(0, $maxDegree + 1, 0);

    $na = count($a);
    $nb = count($b);

    for ($i = 0; $i < $na && $i <= $limit; ++$i) {
        $ai = $a[$i];
        if ($ai === 0) {
            continue;
        }

        $maxJ = min($nb - 1, $limit - $i);
        for ($j = 0; $j <= $maxJ; ++$j) {
            $bj = $b[$j];
            if ($bj === 0) {
                continue;
            }

            $index = $i + $j;
            $value = ($result[$index] + ($ai * $bj) % MOD) % MOD;
            $result[$index] = $value;
        }
    }

    return polyTrim($result);
}

function polyPower(array $base, int $exponent, int $limit): array
{
    $result = [1];
    $base = polyTrim($base);

    while ($exponent > 0) {
        if (($exponent & 1) !== 0) {
            $result = polyMultiply($result, $base, $limit);
        }

        $exponent >>= 1;
        if ($exponent > 0) {
            $base = polyMultiply($base, $base, $limit);
        }
    }

    return $result;
}

$input = trim(stream_get_contents(STDIN));
