$M = intval($data[$index++]);
$K = intval($data[$index++]);

$X = [];
for ($i = 0; $i < $M; ++$i) {
    $X[] = intval($data[$index++]);
}

$specialCount = 0;
for ($i = 0; $i + 1 < $M; ++$i) {
    if ($X[$i] !== $X[$i + 1]) {
        ++$specialCount;
    }
}

$normalCount = $M - $specialCount;
$q = $K - 1;
$totalBlockLength = $N - ($M - 1);

$minimumBlockLength = $M * $q + $specialCount;
if ($minimumBlockLength > $totalBlockLength) {
    echo "0\n";
    exit;
}

$L = $totalBlockLength;

/*
 * normal[len]:
 * Number of words of length len over q symbols in which every symbol occurs.
 */
$normal = array_fill(0, $L + 1, 0);
$used = array_fill(0, $q + 1, 0);
$used[0] = 1;

for ($len = 1; $len <= $L; ++$len) {
    $next = array_fill(0, $q + 1, 0);
    $maxUsed = min($q, $len);

    for ($j = 1; $j <= $maxUsed; ++$j) {
        $value = ($used[$j] * $j) % MOD;
        $value += ($used[$j - 1] * ($q - $j + 1)) % MOD;
        $next[$j] = $value % MOD;
    }

    $used = $next;
    $normal[$len] = $used[$q];
}

/*
 * firstComplete[t]:
 * Number of words whose first occurrence of all q symbols is completed
 * exactly at position t.
 */
$firstComplete = array_fill(0, $L + 1, 0);
for ($t = 1; $t <= $L; ++$t) {
    $previous = ($t >= 2) ? $normal[$t - 1] : 0;
    $value = $normal[$t] - ($q * $previous) % MOD;
    if ($value < 0) {
        $value += MOD;
    }
    $firstComplete[$t] = $value;
}

