 * special[len]:
 * Number of words containing all q symbols such that a distinguished
 * symbol occurs after the first point at which all q symbols have appeared.
 */
$special = array_fill(0, $L + 1, 0);

for ($len = 1; $len <= $L; ++$len) {
    $value = 0;

    for ($t = 1; $t < $len; ++$t) {
        if ($firstComplete[$t] === 0) {
            continue;
        }

        $remaining = $len - $t;
        $tailChoices = $powQ[$remaining] - $powQMinusOne[$remaining];
        if ($tailChoices < 0) {
            $tailChoices += MOD;
