<?php

const MOD = 998244353;

$tokens = preg_split('/\s+/', trim(stream_get_contents(STDIN)));
$N = (int)$tokens[0];
$K = (int)$tokens[1];
$S = $tokens[2];

$base = $N + 2;

// Key encoding: (((count[0] * base + count[1]) * base + count[2]) * 4 + currentState)
$increments = [
    $base * $base * 4,
    $base * 4,
    4,
    0
];

// Initially, the empty prefix is in state 0.
$dp = [$increments[0] => 1];

for ($i = 0; $i < $N; ++$i) {
    $ch = $S[$i];

    if ($ch === '?') {
        $deltas = [1, 2, 3];
    } elseif ($ch === 'A') {
        $deltas = [1];
    } elseif ($ch === 'B') {
        $deltas = [2];
    } else {
        $deltas = [3];
    }

    $next = [];

    foreach ($dp as $key => $ways) {
        $currentState = $key % 4;

        foreach ($deltas as $delta) {
            $nextState = $currentState ^ $delta;
            $nextKey = $key
                + $increments[$nextState]
                + ($nextState - $currentState);

            if (isset($next[$nextKey])) {
                $value = $next[$nextKey] + $ways;
                if ($value >= MOD) {
                    $value -= MOD;
                }
                $next[$nextKey] = $value;
            } else {
                $next[$nextKey] = $ways;
            }
        }
    }

    $dp = $next;
}

$totalPrefixes = $N + 1;
$answer = 0;

foreach ($dp as $key => $ways) {
    $encodedCounts = intdiv($key, 4);

    $count2 = $encodedCounts % $base;
    $encodedCounts = intdiv($encodedCounts, $base);

    $count1 = $encodedCounts % $base;
    $encodedCounts = intdiv($encodedCounts, $base);

    $count0 = $encodedCounts % $base;
    $count3 = $totalPrefixes - $count0 - $count1 - $count2;

    $goodSubstrings =
        intdiv($count0 * ($count0 - 1), 2) +
        intdiv($count1 * ($count1 - 1), 2) +
        intdiv($count2 * ($count2 - 1), 2) +
        intdiv($count3 * ($count3 - 1), 2);

    if ($goodSubstrings >= $K) {
        $answer += $ways;
        if ($answer >= MOD) {
            $answer -= MOD;
        }
    }
}

echo $answer . PHP_EOL;
